list_tax_custom_profiles.code:
const response = await client.taxCustomProfiles.listTaxCustomProfiles({limit: 20});
for (const customProfile of response.map.custom_profiles) {
    console.log(customProfile.id, customProfile.name, customProfile.rate_rules_count);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

create_tax_custom_profile.code:
const response = await client.taxCustomProfiles.createTaxCustomProfile({
    custom_profile: {name: 'Wholesale customers', description: 'Rates for wholesale accounts'},
});
console.log(response.map.custom_profile.id);

